import socket
for host,port in [("127.0.0.1",31337),("board.internal",6667)]:
    try:
        s=socket.create_connection((host,port),timeout=5)
        s.settimeout(5)
        try:
            data=s.recv(4096)
        except Exception as e:
            data=b"<recv err: %s>"%str(e).encode()
        print(host,port,"CONNECTED, banner:",data)
        s.close()
    except Exception as e:
        print(host,port,"FAIL:",e)
